{
  "options": [
    {
      "id": "A",
      "summary": "4章短篇，大嫂苏晚宁从隐忍到炸场，黑卡亮相引发连环反转，第2章付费切割，每章一个打脸高光。",
      "chapters": [
        {
          "num": 1,
          "title": "餐桌上的黑卡",
          "role": "hook_open",
          "core_event": "豪门家宴上，小姑子当众羞辱苏晚宁“吃白食”，婆婆逼她签离婚协议；苏晚宁沉默中随手甩出全球限量黑卡支付天价账单。",
          "emotion": "愤怒→震惊→好奇",
          "hook": "黑卡亮相后，婆婆脸色铁青，小姑子尖叫“假的！”，苏晚宁嘴角微扬——下一秒，银行经理亲自赶到。",
          "beat": "【场景目的】建立女主被欺压的弱势形象，引爆黑卡悬念。\n【核心动作】羞辱→黑卡出场→众人震惊。\n【节奏档位】快\n【结尾钩子】经理进门，小姑子慌乱。",
          "intent": {
            "ai_suggest": "羞辱+黑卡亮相+反转+愤怒+代入女主"
          }
        },
        {
          "num": 2,
          "title": "限量黑卡背后",
          "role": "paywall",
          "core_event": "银行经理确认黑卡真实且为全球仅三张的至尊级，婆婆态度剧变，小姑子不甘心揭发女主“靠男人”；苏晚宁淡然拨出一个电话，电话那头响起全亚洲首富的声音。",
          "emotion": "持续震惊→怀疑→崇拜",
          "hook": "电话挂断，苏晚宁淡淡道：“我自己的公司，还需要靠男人？”——屏幕切到新闻头条：神秘女富豪收购家族企业。",
          "beat": "【场景目的】深度打脸，揭示女主隐藏实力，制造付费冲动。\n【核心动作】验证黑卡→揭发→电话首富。\n【节奏档位】快\n【结尾钩子】新闻头条出现，女主身份悬念升级。",
          "intent": "读者极度好奇女主真实身份，期待她全面碾压恶人，付费意愿达到峰值。"
        },
        {
          "num": 3,
          "title": "她才是掌权者",
          "role": "paid_open",
          "core_event": "苏晚宁亮出家族企业控股文件，原来她才是背后最大股东，当场撤换婆婆的管理权，小姑子被扫地出门。丈夫赶回跪求原谅。",
          "emotion": "爽快、解气、征服感",
          "hook": "丈夫抱住她腿：“晚宁，我错了！” 苏晚宁看着钻戒：“从今天起，你听我的。”",
          "beat": "【场景目的】付费后立即返还爽感，彻底翻盘。\n【核心动作】亮身份→夺权→丈夫下跪。\n【节奏档位】中\n【结尾钩子】夫妻关系反转，预示下一章更高能。"
        },
        {
          "num": 4,
          "title": "新女王登基",
          "role": "finale",
          "core_event": "家族旗下所有产业易主，苏晚宁召开董事会全面改革；婆婆和小姑子灰溜溜搬出豪宅；丈夫宣布放弃继承权安心做家庭煮夫。最后镜头：苏晚宁签下百亿合同，对助理说“把我前夫的那家小公司也收了。”",
          "emotion": "酣畅淋漓、圆满、爽到极致",
          "hook": "尾声彩蛋：苏晚宁手机响起——国际神秘组织邀请她担任荣誉会长。",
          "beat": "【场景目的】完成终极打脸，收束所有伏笔，给人留下“她还有更大舞台”的期待。\n【核心动作】夺回一切→前夫家庭煮夫→新事业启航。\n【节奏档位】慢（松弛有度）\n【结尾钩子】神秘邀请，开放式遐想。",
          "intent": {
            "core_task": {
              "opening_gap": "从被嫌弃的“废柴大嫂”到全球商业女王",
              "freeze_frame": "苏晚宁站在顶楼落地窗前俯瞰城市，身后是巨额合同",
              "open_ending": false
            }
          }
        }
      ]
    }
  ]
}
